using namespace visual;namespace{constexpr double pi=std::numbers::pi,tau=2*pi,scale=13./693.;constexpr std::array<SDL_Rect,4>cells{{{52,39,417,693},{570,20,417,706},{1089,33,417,681},{1607,25,417,688}}};double noise(int side,int wagon,int salt){const std::string key=std::to_string(side)+"/"+std::to_string(wagon);std::uint32_t text=5381;for(unsigned char c:key)text=text*33+c;const auto seed=art::finish(art::mix(art::serial_hash(salt),art::mix(text,art::mix(28))));const double n=std::sin(double(seed%100000)*12.9898)*43758.5453;return n-std::floor(n);}Color multiply(Color a,Color b){return{a.r*b.r,a.g*b.g,a.b*b.b,a.a*b.a};}}
void TacticalWeapons::fire(int side,int wagon,const std::string&kind){auto&r=rigs_[{side,wagon}];r.side=side;r.wagon=wagon;r.kind=kind;if(kind=="machinegun")r.window=12;else{r.recoil=2.5;r.heat=std::min(1.,r.heat+.3);}}
TacticalWeapons::Rig TacticalWeapons::rig(int side,int wagon)const{const auto f=rigs_.find({side,wagon});return f==rigs_.end()?Rig{}:f->second;}
std::vector<TacticalWeapons::Round>TacticalWeapons::step(){std::vector<Round>out;for(auto&[key,r]:rigs_){++r.age;const double target=r.window>0?42:0;r.speed+=(target-r.speed)*(r.window>0?.25:.06);r.phase=std::fmod(r.phase+r.speed*.02,tau);r.recoil*=r.kind=="machinegun"?.55:.82;r.heat*=.993;if(r.window>0){--r.window;if(r.speed>42*.6&&r.age%2==0){++r.rounds;r.recoil=.6;r.heat=std::min(1.,r.heat+.035);out.push_back({r.side,r.wagon,r.rounds,r.heat});}}}std::erase_if(rigs_,[](const auto&p){const auto&r=p.second;return!r.window&&r.speed<.05&&r.heat<.02&&r.recoil<.01;});return out;}
Point TacticalWeapons::extent(int side,bool gun){if(gun)return{417*scale,(side==0?693-310:693)*scale};return{8.5,side==0?5.5:10.};}
double TacticalWeapons::reach(int side,bool gun){if(gun)return side==0?-(693-480)*scale:13.;return side==0?-2.5:8.5;}
void TacticalWeapons::settle(const combat::TacticalState&s,const std::function<WeaponGeometry(int,int)>&geometry,LivingEffects&living,Point world_offset){for(int side=0;side<2;++side)for(int wagon=0;wagon<int(s.trains[side].size());++wagon){const auto&car=s.trains[side][wagon];if(car.kind!=combat::Cannon&&car.kind!=combat::MachineGun)continue;const auto key=std::pair{side,wagon};const auto g=geometry(side,wagon);const auto size=extent(side,car.kind==combat::MachineGun);const double center=g.box.x+g.box.w/2;if(!resting_.contains(key)){resting_[key]={0,g.surface(center)+1.8-size.y/2,0,0,0,0,car.health,0};continue;}auto&body=resting_[key];const double lean=noise(side,wagon,car.health)<.5?-1:1;if(car.health<body.health){if(car.health<=0){body.vy=-1.3;body.vx=lean*(.06+.08*noise(side,wagon,7));body.spin=lean*(.12+.1*noise(side,wagon,9));body.rest=lean*(pi/2-.25*noise(side,wagon,11));}else{body.spin=lean*.02;body.rest=lean*(.15+.2*noise(side,wagon,13));}body.health=car.health;}const double x=std::clamp(center+body.x,double(g.box.x+2),double(g.box.x+g.box.w-2));body.x=x-center;const double ground=g.surface(x)+(car.health>=3?1.8:3);double half=(std::abs(size.y*std::cos(body.angle))+std::abs(size.x*std::sin(body.angle)))/2;const bool airborne=body.y+half<ground-.01||body.vy<0;if(airborne){body.vy+=.12;body.y+=body.vy;body.x+=body.vx;body.angle+=body.spin;half=(std::abs(size.y*std::cos(body.angle))+std::abs(size.x*std::sin(body.angle)))/2;}if(body.y+half>=ground){body.y=ground-half;if(body.vy>.8){living.add("dust",Point{x,ground}+world_offset,{0,-1},std::clamp(body.vy/3,.4,1.));living.add("sparks",Point{x,ground}+world_offset,{0,-1},.5);body.vy=-body.vy*.3;body.vx*=.5;body.spin*=.4;}else{body.vy=0;body.vx*=.6;body.spin=0;body.angle+=(body.rest-body.angle)*.2;if(std::abs(body.vx)<.02)body.vx=0;}}}}
WeaponMount TacticalWeapons::mount(const WeaponGeometry&g,int side,int wagon,bool gun)const{const auto r=rig(side,wagon);const auto size=extent(side,gun);const auto found=resting_.find({side,wagon});const Rest*rest=found==resting_.end()?nullptr:&found->second;const double x=g.box.x+g.box.w/2,foot=rest?rest->y+size.y/2:g.surface(x)+1.8;WeaponMount at;at.base={x,foot};at.direction={0,side==0?1.:-1.};at.body=at.base-at.direction*r.recoil;at.muzzle=at.body+at.direction*reach(side,gun);const Point shift{rest?rest->x:0,0};at.base=at.base+shift;at.body=at.body+shift;at.muzzle=at.muzzle+shift;at.breech=at.body+Point{2.5,side==0?-3.5:-2.};at.angle=rest?rest->angle:0;at.pivot=at.base-Point{0,size.y/2};if(at.angle!=0){at.muzzle=at.pivot+rotated(at.muzzle-at.pivot,at.angle);at.breech=at.pivot+rotated(at.breech-at.pivot,at.angle);at.direction=rotated(at.direction,at.angle);}return at;}
void TacticalWeapons::draw(Canvas&canvas,const std::filesystem::path&assets,const WeaponGeometry&g,int side,int wagon,bool machine,int health)const{const auto r=rig(side,wagon);auto at=mount(g,side,wagon,machine);if(at.angle!=0)at.muzzle=at.pivot+rotated(at.muzzle-at.pivot,-at.angle);Color tint=side==1?Color{1,.77,.66,1}:Color{1,1,1,1};if(health<=0)tint=multiply(tint,{.78,.72,.68,1});const auto transform=[&](Point p){return at.pivot+rotated(p-at.pivot,at.angle);};auto poly=[&](std::vector<Point>p,Color c){for(auto&v:p)v=transform(v);polygon(canvas,p,c);};auto ln=[&](Point a,Point b,double w,Color c){line(canvas,transform(a),transform(b),w,c);};auto bx=[&](Point p,Point size,Color c){p=snap(p);size=snap(size);poly({p,p+Point{size.x,0},p+size,p+Point{0,size.y}},c);};auto disc=[&](Point p,double radius,Color c){circle(canvas,transform(p),radius,c);};auto plate=[&](Point center,Point half,Color fill,Color rim){std::vector<Point>p;for(int i=0;i<16;++i)p.push_back(center+Point{std::cos(tau*i/16)*half.x,std::sin(tau*i/16)*half.y});poly(p,fill);for(int i=0;i<16;++i)ln(p[i],p[(i+1)%16],.25,rim);};const auto steel=multiply(color(0x2a343e),tint),dark=multiply(color(0x11171d),tint),light=multiply(color(0x8796a2),tint),brass=multiply(color(0xb8873a),tint),brass_light=multiply(color(0xe8bd68),tint);const auto bore=color(0x05080b);auto shield=[&](Point foot,double h){const double top=foot.y-h;poly({{foot.x-4.25,foot.y},{foot.x-3.5,top+1},{foot.x-2.5,top},{foot.x+2.5,top},{foot.x+3.5,top+1},{foot.x+4.25,foot.y}},steel);ln({foot.x-4,foot.y-.25},{foot.x-3.25,top+1},.5,light);ln({foot.x-2.25,top+.25},{foot.x+2.25,top+.25},.5,color(0xe8f0f5));ln({foot.x+3.75,foot.y},{foot.x+3.1,top+1.2},.5,dark);for(double x:{-3.,-1.,1.,3.})bx({foot.x+x-.125,foot.y-1},{.25,.25},brass_light);};auto heat=[&](Point p,Point size){if(r.heat<=.15)return;for(int band=0;band<4;++band)bx(p+Point{0,size.y*band/4},{size.x,size.y/4},{1,.38,.1,(r.heat-.15)*.5*(1-band/4.)});};
    auto image=[&](SDL_Rect crop,Point p,Point size){auto*t=canvas.texture(assets/"weapons/gatling.png");SDL_SetTextureScaleMode(t,SDL_ScaleModeNearest);int tw{},th{};SDL_QueryTexture(t,nullptr,nullptr,&tw,&th);const float s=std::min(canvas.width()/320.f,canvas.height()/200.f),left=(canvas.width()-320*s)/2,top=(canvas.height()-200*s)/2;std::array<SDL_Vertex,4>v;const std::array<Point,4>q{{{0,0},{1,0},{1,1},{0,1}}};p=snap(p);for(int i=0;i<4;++i){const Point screen=transform(p+Point{q[i].x*size.x,q[i].y*size.y});v[i]={{left+float(screen.x)*s,top+float(screen.y)*s},sdl(tint),{float(crop.x+q[i].x*crop.w)/tw,float(crop.y+q[i].y*crop.h)/th}};}const int indices[]={0,1,2,0,2,3};render_check(SDL_RenderGeometry(canvas.renderer(),t,v.data(),4,indices,6),"Gatling sprite");};
    const Point foot=at.body,face=at.muzzle;
    if(machine){const auto cell=cells[r.speed<4?0:int(r.phase/tau*12)%4];if(side==0){const SDL_Rect base{cell.x,cell.y+310,cell.w,cell.h-310};const Point size{base.w*scale,base.h*scale};image(base,foot-Point{size.x/2,size.y},size);const Point capsize{125*scale*2,78*scale*2};image({cell.x+145,cell.y,125,78},face-capsize*.5,capsize);if(r.heat>.15)disc(face,capsize.x*.45,{1,.4,.12,(r.heat-.15)*.45});}else{const Point size{cell.w*scale,cell.h*scale};image(cell,foot-Point{size.x/2,size.y},size);heat({foot.x-1.25,foot.y-size.y+.5},{2.5,size.y*.5});}return;}
    plate(foot+Point{0,.5},{5,1.25},dark,brass);if(side==0){shield(foot,5.5);bx(face-Point{2,1.25},{4,2.5},dark);bx(face-Point{2,1.25},{4,.5},light);disc(face,1.25,steel);for(int i=0;i<5;++i)ln(face+from_angle(pi*1.05+(pi*1.7-pi*1.05)*i/5)*1.25,face+from_angle(pi*1.05+(pi*1.7-pi*1.05)*(i+1)/5)*1.25,.5,brass_light);disc(face,.75,bore);if(r.heat>.1)disc(face,.75,{1,.45,.15,r.heat*.6});bx(face+Point{-1.75,-.25},{.5,.5},bore);bx(face+Point{1.25,-.25},{.5,.5},bore);}else{const double top=foot.y-4.5;poly({{foot.x-1.5,top},{face.x-1.1,face.y+1},{face.x+1.1,face.y+1},{foot.x+1.5,top}},steel);ln({foot.x-.9,top},{face.x-.6,face.y+1},.5,light);ln({foot.x+1.1,top},{face.x+.8,face.y+1},.5,dark);bx({foot.x-1.5,top+(face.y-top)*.45},{3,.5},brass);bx(face+Point{-2,-.25},{4,1.75},dark);bx(face+Point{-2,-.25},{4,.5},light);bx(face+Point{-1.5,.75},{.75,.5},bore);bx(face+Point{.75,.75},{.75,.5},bore);heat({face.x-1.25,face.y},{2.5,(top-face.y)*.6});shield(foot,4.5);bx(foot+Point{-1.75,-2},{3.5,2.5},dark);bx(foot+Point{-1.75,-2},{3.5,.5},steel);bx(foot+Point{-.5,-1.25},{1,1},brass_light);}}
